CREATE TABLE installation_email_contents (
 kind text NOT NULL CHECK(kind IN ('invitation','invitation_accepted','password_reset','assignment','approval','approval_result','test')),
 language text NOT NULL CHECK(language IN ('es','en')),
 subject text NOT NULL CHECK(octet_length(subject) BETWEEN 1 AND 1000),
 body_html text NOT NULL CHECK(octet_length(body_html) BETWEEN 1 AND 100000),
 revision bigint NOT NULL DEFAULT 1 CHECK(revision>0),
 PRIMARY KEY(kind,language)
);
