INSERT INTO installation_email_contents(kind,language,subject,body_html) VALUES('invitation','es','Invitación a {{organization_name}}','<p>Hola {{recipient_name}},</p><p>{{inviter_name}} te invita a colaborar en {{organization_name}}.</p><p><a href="{{invitation_url}}">Aceptar invitación</a></p><p>La invitación vence el {{expires_at}}. Si no esperabas este correo, puedes ignorarlo.</p>');
INSERT INTO installation_email_contents(kind,language,subject,body_html) VALUES('invitation','en','Invitation to {{organization_name}}','<p>Hello {{recipient_name}},</p><p>{{inviter_name}} invites you to collaborate at {{organization_name}}.</p><p><a href="{{invitation_url}}">Accept invitation</a></p><p>The invitation expires on {{expires_at}}. If you were not expecting this email, you can ignore it.</p>');
INSERT INTO installation_email_contents(kind,language,subject,body_html) VALUES('invitation_accepted','es','{{member_name}} se unió a {{organization_name}}','<p>Hola {{recipient_name}},</p><p>{{member_name}} ha aceptado la invitación y se ha unido a {{organization_name}}.</p>');
INSERT INTO installation_email_contents(kind,language,subject,body_html) VALUES('invitation_accepted','en','{{member_name}} joined {{organization_name}}','<p>Hello {{recipient_name}},</p><p>{{member_name}} has accepted the invitation and joined {{organization_name}}.</p>');
INSERT INTO installation_email_contents(kind,language,subject,body_html) VALUES('password_reset','es','Recupera tu acceso a {{organization_name}}','<p>Hola {{recipient_name}},</p><p>Recibimos una solicitud para recuperar tu contraseña en {{organization_name}}.</p><p><a href="{{reset_url}}">Restablecer contraseña</a></p><p>El enlace vence el {{expires_at}}. Si no lo solicitaste, ignora este correo.</p>');
INSERT INTO installation_email_contents(kind,language,subject,body_html) VALUES('password_reset','en','Recover your access to {{organization_name}}','<p>Hello {{recipient_name}},</p><p>We received a password recovery request for your account at {{organization_name}}.</p><p><a href="{{reset_url}}">Reset password</a></p><p>The link expires on {{expires_at}}. If you did not request it, ignore this email.</p>');
INSERT INTO installation_email_contents(kind,language,subject,body_html) VALUES('assignment','es','Tarea asignada · {{organization_name}}','<p>Hola {{recipient_name}},</p><p>Tienes una tarea asignada en <strong>{{project_name}}</strong>.</p><p>Referencia: {{resource_id}}</p><p>Ingresa a Nexora para consultar los detalles actuales.</p>');
INSERT INTO installation_email_contents(kind,language,subject,body_html) VALUES('assignment','en','Task assignment · {{organization_name}}','<p>Hello {{recipient_name}},</p><p>A task has been assigned to you in <strong>{{project_name}}</strong>.</p><p>Reference: {{resource_id}}</p><p>Sign in to Nexora to view the current details.</p>');
INSERT INTO installation_email_contents(kind,language,subject,body_html) VALUES('approval','es','Solicitud de aprobación · {{organization_name}}','<p>Hola {{recipient_name}},</p><p>Hay una solicitud pendiente de tu revisión en <strong>{{project_name}}</strong>.</p><p>Referencia: {{resource_id}}</p><p>Ingresa a Nexora para revisar y decidir.</p>');
INSERT INTO installation_email_contents(kind,language,subject,body_html) VALUES('approval','en','Approval requested · {{organization_name}}','<p>Hello {{recipient_name}},</p><p>A request is awaiting your review in <strong>{{project_name}}</strong>.</p><p>Reference: {{resource_id}}</p><p>Sign in to Nexora to review and decide.</p>');
INSERT INTO installation_email_contents(kind,language,subject,body_html) VALUES('approval_result','es','Resultado de aprobación · {{organization_name}}','<p>Hola {{recipient_name}},</p><p>La solicitud {{resource_id}} de {{project_name}} tiene el siguiente resultado: <strong>{{decision}}</strong>.</p><p>{{reason}}</p>');
